// =========================================================================================
// ПОИСКОВЫЙ ДВИЖОК ПО БАЗЕ
// =========================================================================================
function searchDopogGoods(query) {
  if (!query) return window.DOPOG_DATABASE.slice(0, 15);
  const q = String(query).trim().toLowerCase().replace(/^оон\s*/i, '').replace(/^un\s*/i, '');
  return window.DOPOG_DATABASE.filter(item => 
    item.un.includes(q) || 
    item.name_ru.toLowerCase().includes(q) ||
    item.class.toLowerCase().includes(q)
  );
}

// =========================================================================================
// ГЕНЕРАТОР ОФИЦИАЛЬНОЙ ЗАПИСИ ДЛЯ ТРАНСПОРТНОЙ НАКЛАДНОЙ (п. 5.4.1.1.1 ДОПОГ)
// =========================================================================================
function buildAdrConsignmentEntry(good) {
  const parts = [];
  parts.push(`UN ${good.un}`);
  parts.push(good.name_ru.toUpperCase());
  parts.push(good.class);
  if (good.pg && good.pg !== "-") {
    parts.push(`ГУ ${good.pg}`);
  }
  if (good.tunnel) {
    parts.push(good.tunnel);
  }
  return parts.join(", ");
}

// =========================================================================================
// ЭКСПЕРТНЫЙ АЛГОРИТМ ОЦЕНКИ ОГПО ДЛЯ ВСЕХ НОМЕРОВ ООН (ВКЛЮЧАЯ КЛАСС 1)
// =========================================================================================
function evaluatePackageCargo(unCode, amountKg = null) {
  const code = String(unCode).trim().replace(/[^0-9]/g, '').padStart(4, '0');
  const found = window.DOPOG_DATABASE.find(item => item.un === code);

  if (found) {
    const consignmentText = buildAdrConsignmentEntry(found);

    if (!found.is_hcdg) {
      return {
        un: found.un,
        name: found.name_ru,
        class: found.class,
        pg: found.pg,
        tunnel: found.tunnel,
        labels: found.labels,
        consignmentText,
        requires_permit: false,
        badge_type: "success",
        status_text: "СПЕЦРАЗРЕШЕНИЕ В УПАКОВКАХ НЕ ТРЕБУЕТСЯ",
        reason: `В упаковках и бочках класс ${found.class} не относится к грузам повышенной опасности (ДОПОГ 1.10.3.1.2). Спецразрешение НЕ требуется.`,
        note: "Груз перевозится по стандартным правилам ДОПОГ и правилу 1000 баллов."
      };
    } else {
      if (found.threshold === 0) {
        return {
          un: found.un,
          name: found.name_ru,
          class: found.class,
          pg: found.pg,
          tunnel: found.tunnel,
          labels: found.labels,
          consignmentText,
          requires_permit: true,
          badge_type: "danger",
          status_text: "ТРЕБУЕТСЯ СПЕЦИАЛЬНОЕ РАЗРЕШЕНИЕ (ОГПО)",
          reason: `Вещество / изделие класса ${found.class}. Согласно Таблице 1.10.3.1.2 ДОПОГ относится к грузам повышенной опасности (ОГПО) при любом количестве (порог 0 кг).`,
          note: "Спецразрешение Ространснадзора ОБЯЗАТЕЛЬНО независимо от массы или объема партии."
        };
      } else if (found.threshold > 0) {
        if (amountKg !== null && amountKg > found.threshold) {
          return {
            un: found.un,
            name: found.name_ru,
            class: found.class,
            pg: found.pg,
            tunnel: found.tunnel,
            labels: found.labels,
            consignmentText,
            requires_permit: true,
            badge_type: "danger",
            status_text: `ТРЕБУЕТСЯ СПЕЦРАЗРЕШЕНИЕ (Масса ${amountKg} кг > порога ${found.threshold} кг)`,
            reason: `Вещество класса ${found.class}. Согласно ДОПОГ 1.10.3.1.2 относится к ОГПО при массе БОЛЕЕ ${found.threshold} кг.`,
            note: "Требуется получение специального разрешения Ространснадзора."
          };
        } else if (amountKg !== null && amountKg <= found.threshold) {
          return {
            un: found.un,
            name: found.name_ru,
            class: found.class,
            pg: found.pg,
            tunnel: found.tunnel,
            labels: found.labels,
            consignmentText,
            requires_permit: false,
            badge_type: "success",
            status_text: `СПЕЦРАЗРЕШЕНИЕ НЕ ТРЕБУЕТСЯ (Масса ${amountKg} кг <= ${found.threshold} кг)`,
            reason: `Масса партии не превышает установленный порог ОГПО ${found.threshold} кг (ДОПОГ 1.10.3.1.2).`,
            note: "Перевозка осуществляется по стандартному допуску ДОПОГ."
          };
        } else {
          return {
            un: found.un,
            name: found.name_ru,
            class: found.class,
            pg: found.pg,
            tunnel: found.tunnel,
            labels: found.labels,
            consignmentText,
            requires_permit: true,
            badge_type: "warning",
            status_text: `ТРЕБУЕТСЯ СР ПРИ МАССЕ БОЛЕЕ ${found.threshold} КГ`,
            reason: `Груз относится к ОГПО только при превышении порогового значения ${found.threshold} кг.`,
            note: "Укажите массу партии для окончательного расчета."
          };
        }
      }
    }
  }

  // Общий резервный расчет для номеров вне текущей части
  const num = parseInt(code, 10);
  if (num > 0 && num <= 510) {
    const defaultEntry = `UN ${code}, ВЗРЫВЧАТОЕ ВЕЩЕСТВО ИЛИ ИЗДЕЛИЕ, 1, (B1000C)`;
    return {
      un: code,
      name: "Взрывчатое вещество или изделие (Класс 1)",
      class: "1",
      pg: "-",
      tunnel: "(B1000C)",
      labels: ["1"],
      consignmentText: defaultEntry,
      requires_permit: true,
      badge_type: "danger",
      status_text: "ТРЕБУЕТСЯ СПЕЦИАЛЬНОЕ РАЗРЕШЕНИЕ (ОГПО Класс 1)",
      reason: "Согласно ДОПОГ 1.10.3.1.2 взрывчатые материалы подклассов 1.1, 1.2, 1.3C, 1.5, 1.6 в любых количествах являются ОГПО.",
      note: "Требуется спецразрешение Ространснадзора и организация охраны/сопровождения."
    };
  }

  const genericEntry = `UN ${code}, ОПАСНЫЙ ГРУЗ В УПАКОВКАХ, ДОПОГ, (E)`;
  return {
    un: code,
    name: "Опасный груз ДОПОГ в таре / упаковках",
    class: "ДОПОГ",
    pg: "-",
    tunnel: "(E)",
    labels: ["ДОПОГ"],
    consignmentText: genericEntry,
    requires_permit: false,
    badge_type: "success",
    status_text: "СПЕЦРАЗРЕШЕНИЕ В УПАКОВКАХ НЕ ТРЕБУЕТСЯ",
    reason: "Для данного номера ООН при перевозке в упаковках/бочках статус груза повышенной опасности (ОГПО) по ДОПОГ 1.10.3.1.2 не установлен.",
    note: "Груз перевозится по стандартным свидетельствам ДОПОГ. Спецразрешение Ространснадзора не оформляется."
  };
}




